def generate(seed):
    r = random.Random(seed)
    def isp(x):
        if x < 2:
            return False
        if x % 2 == 0:
            return x == 2
        i = 3
        while i * i <= x:
            if x % i == 0:
                return False
            i += 2
        return True
    def rp(a, b):
        while True:
            v = r.randrange(a, b)
            if isp(v):
                return v
    p = rp(50, 1000) if r.random() < 0.3 else rp(1000, 100000)
    q = rp(100000, 3000000)
    return str(p * q)

